
ALTER TABLE `Order` MODIFY status ENUM('PENDIENTE','CONFIRMADO','PREPARANDO','DESPACHADO','VALIDANDO','ENVIANDO_A_DROPI','ACEPTADO_POR_DROPI','ERROR_DROPI','GUIA_GENERADA','EN_TRANSITO','EN_REPARTO','ENTREGADO','DEVUELTO','CANCELADO') NOT NULL DEFAULT 'PENDIENTE';
ALTER TABLE TrackingEvent MODIFY status ENUM('PENDIENTE','CONFIRMADO','PREPARANDO','DESPACHADO','VALIDANDO','ENVIANDO_A_DROPI','ACEPTADO_POR_DROPI','ERROR_DROPI','GUIA_GENERADA','EN_TRANSITO','EN_REPARTO','ENTREGADO','DEVUELTO','CANCELADO') NOT NULL;
ALTER TABLE Customer ADD COLUMN phoneNormalized VARCHAR(191) NULL;
ALTER TABLE `Order` ADD COLUMN paymentMethod VARCHAR(191) NOT NULL DEFAULT 'CONTRAENTREGA', ADD COLUMN pricingSnapshot JSON NULL;
ALTER TABLE Notification ADD COLUMN attempts INTEGER NOT NULL DEFAULT 0, ADD COLUMN sentAt DATETIME(3) NULL, ADD COLUMN lastError VARCHAR(191) NULL;
CREATE TABLE NotificationPart (
 id VARCHAR(191) NOT NULL, notificationId VARCHAR(191) NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL,
 status VARCHAR(191) NOT NULL DEFAULT 'PENDING', attempts INTEGER NOT NULL DEFAULT 0, messageId VARCHAR(191) NULL,
 sentAt DATETIME(3) NULL, startedAt DATETIME(3) NULL, lastError VARCHAR(191) NULL,
 PRIMARY KEY(id), UNIQUE INDEX NotificationPart_notificationId_position_key(notificationId,position),
 CONSTRAINT NotificationPart_notificationId_fkey FOREIGN KEY(notificationId) REFERENCES Notification(id) ON DELETE CASCADE ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE TelegramLinkCode (
 id VARCHAR(191) NOT NULL, codeHash VARCHAR(191) NOT NULL, adminId VARCHAR(191) NOT NULL, sessionId VARCHAR(191) NOT NULL,
 expiresAt DATETIME(3) NOT NULL, usedAt DATETIME(3) NULL, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 PRIMARY KEY(id), UNIQUE INDEX TelegramLinkCode_codeHash_key(codeHash)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
